const translations={en:{title:"Timeless Stories — Official Book Hub",subtitle:"Quick access to all volumes and languages",select:"Select volume",qr:"Show QR Code",qrTitle:"Scan to open this page",close:"Close",followMe:"Follow me"},es:{title:"Historias Eternas — Centro oficial de libros",subtitle:"Acceso rápido a todos los volúmenes e idiomas",select:"Seleccionar volumen",qr:"Mostrar código QR",qrTitle:"Escanea para abrir esta página",close:"Cerrar",followMe:"Sígueme"},fr:{title:"Légendes Éternelles — Plateforme officielle des livres",subtitle:"Accès rapide à tous les volumes et langues",select:"Sélectionner le volume",qr:"Afficher le code QR",qrTitle:"Scannez pour ouvrir cette page",close:"Fermer",followMe:"Suivez-moi"}};function detectLang(){const e=(navigator.language||"en").slice(0,2);return translations[e]?e:"en"}function applyTranslations(){const e=detectLang(),t=translations[e];document.getElementById("title").innerHTML=t.title,document.getElementById("subtitle").innerHTML=t.subtitle,document.getElementById("selectLabel").textContent=t.select,document.getElementById("qrButton").textContent=t.qr,document.getElementById("qrTitle").textContent=t.qrTitle,document.getElementById("closeModal").textContent=t.close,document.getElementById("followMe").textContent=t.followMe}applyTranslations();const data={"Volume 1":{preview:"img/volume1.png",links:{English:"https://a.co/d/1HQh5JM","Español":"https://a.co/d/5RiXGEZ","Français":"https://a.co/d/7EyHZZm"}},"Volume 2":{preview:"img/volume2.png",links:{English:"https://a.co/d/0HYJyAp","Español":"https://a.co/d/9GF2Ug3"}},"Spanish Mirrors (Upcoming)":{preview:"img/mirrors.png",links:{"Notify me":"https://amzn.to/3YXGR5W"}}},select=document.getElementById("volumeSelect"),linksContainer=document.getElementById("linksContainer"),previewImage=document.getElementById("previewImage");function renderVolume(e){const t=data[e];linksContainer.innerHTML="",Object.entries(t.links).forEach((([e,t])=>{const n=document.createElement("a");n.className="link-btn",n.href=t,n.target="_blank",n.textContent=e,linksContainer.appendChild(n)})),previewImage.src=t.preview}Object.keys(data).forEach((e=>{const t=document.createElement("option");t.value=e,t.textContent=e,select.appendChild(t)})),select.addEventListener("change",(e=>{renderVolume(e.target.value)}));const qrButton=document.getElementById("qrButton"),qrModal=document.getElementById("qrModal"),closeModal=document.getElementById("closeModal"),qrImage=document.getElementById("qrImage");function generateQR(){const e=window.location.href;qrImage.src=`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(e)}`}qrButton.addEventListener("click",(e=>{e.preventDefault(),generateQR(),qrModal.style.display="flex"})),closeModal.addEventListener("click",(e=>{e.preventDefault(),qrModal.style.display="none"})),qrModal.addEventListener("click",(e=>{e.target===qrModal&&(qrModal.style.display="none")}));const firstKey=Object.keys(data)[0];select.value=firstKey,renderVolume(firstKey);